  var left = Math.max(8, Math.min(window.innerWidth - 290, rect.left));
  var top = rect.bottom + 8;
  if (top + 160 > window.innerHeight) top = rect.top - 170;
  tip.style.left = left + 'px';
  tip.style.top = top + 'px';
}
```

